head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/digital_recv_common.js");
scwin.vScrenID = "ULDSTF70015.xml"; //화면ID

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vAcptNo = "";
scwin.clickListBzTpCd = ""; //상장업무구분코드 (그리드 로우 클릭시 상장업무구분코드를 획득함)
scwin.clickBzProcsNo = ""; //업무처리번호 (클릭된)

scwin.readOnlyYn = "N";
scwin.procJob = "";
scwin.logicPackYn = "Y";
scwin.clickIsuCd = ""; //종목코드(클릭된)
scwin.clickAddIsuRnd = ""; //추가상장차수(클릭된)
scwin.clickListEtpProdTpCd = ""; // ETP상품구분코드(클릭된)
scwin.vListInit = true;
scwin.logicPackYn = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};



/********************************************** 
 * 함수명 : fn_list_sync()
 * 설명    :  상장신청접수 에 대한 목록 조회
 **********************************************/
scwin.fn_list_sync = function() {
    var v_listBzTpCd = "";
    var urlcond = '';
    urlcond += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    urlcond += "&ISU_CD=" + txb_ISU_CD.getValue();
    urlcond += "&LIST_SDATE=" + $c.stf.getObjectValue(edt_ListSDate);
    urlcond += "&LIST_EDATE=" + $c.stf.getObjectValue(edt_ListEDate);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        // 디지털증권 신규상장 청구
        v_listBzTpCd = "781";
        var url = "/digital/DigitalListedRcv.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalReceipt";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += urlcond;
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        // 디지털증권 추가상장 청구
        v_listBzTpCd = "784";
        var url = "/digital/DigitalListedRcv.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalReceipt";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += urlcond;
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    }
};




/********************************************** 
 * 함수명 : fn_setBzProcsNo()
 * 설명    : (신규접수)클릭된 그리드에 대한 업무처리번호 획득
 **********************************************/
scwin.fn_setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(eval(obj), "BZ_PROCS_NO");
    scwin.clickListBzTpCd = dtsObj.getCellData(eval(obj), "LIST_BZ_TP_CD");
    //alert('clickListBzTpCd : ' + clickListBzTpCd );

};




/********************************************** 
 * 함수명 : fn_OpenNewWin()
 * 설명    :  상장신청접수 에 대한 상세 팝업조회
 **********************************************/
scwin.fn_OpenNewWinForDgse = async function(row, dtsObj) {
    scwin.fn_setBzProcsNo(row, dtsObj);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        await $c.frame.CreateDialogFrame("DGSE_NLIST", "/digital/ULDSTF70050.gfm", "신규상장", 10, 10, 1070, 820, "window");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        await $c.frame.CreateDialogFrame("DGSE_NLIST", "/digital/ULDSTF70051.gfm", "추가상장", 10, 10, 1060, 820, "window");
    }
};



/********************************************** 
 * 함수명 : fn_SetParIsur2()
 * 설명    : 상장신청인 선택 팝업호출용
 **********************************************/
scwin.fn_SetParIsur2 = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].ISUR_NM);
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명 : fn_SetParIsu()
 * 설명    : 종목코드 선택 팝업호출용
 **********************************************/
scwin.fn_SetParIsu = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "신규상장목록", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "추가상장목록", "", "8");
    }
};



/********************************************** 
 * 신규/추가상장의 목록검색시작일과 종료일자의 초기값 설정
 ***********************************************/
scwin.fn_initSearchDate = function(edtSDate, edtEDate) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edtSDate.setValue('19000101');
    edtEDate.setValue($c.ut.cGetPlusDate2(vCurDate, 60));
};
scwin.fn_set_code = function() {
    dts_EtnInst.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_EtnInst.Reset();
    //alert("call");

};
scwin.fn_GetParIsur2 = function(arrPar) {
    arrPar[0] = "lds.stf.digital.select.isuracptlist.condition";
    return arrPar.length;
};
scwin.fn_GetParIsu = function(arrPar) {
    arrPar[0] = "lds.stf.digital.select.isuacptlist.condition";
    return arrPar.length;
};
scwin.gform_onload = function() {
    $c.pre_newlisting.fn_initSearchDate(edt_ListSDate, edt_ListEDate);
    var usrCBData = "1주일전^1,1개월전^2,3개월전^3,6개월전^4,1년전^5,2년전^6";
    cmb_PeriodTp.CBData = usrCBData; //사용자CBData 지정

    MaxTab_01.setSelectedTabIndex(1);
    scwin.fn_set_code();
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_1_OnLoadError = function() {
    //alert('dts_List_1.OnLoadError()');

    //alert_error(dts_List_1);

};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    //alert('dts_List_2.OnLoadCompleted('+rowcount+')');
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    //신규상장접수 > Grid Row Click
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWinForDgse(row, dts_List_1);
    }
};
scwin.grd_List_2_OnDblClick = function(row, colid) {
    //신규상장접수 > Grid Row Click
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWinForDgse(row, dts_List_2);
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_ListSDate, edt_ListEDate);
};
scwin.img_ReqEDate_onclick = function() {
    popUpCalendar2(edt_ListEDate);
};
scwin.img_ReqSDate_onclick = function() {
    popUpCalendar2(edt_ListSDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_IsuSearch_onclick = function() {
    scwin.fn_SetPar = fn_SetParIsur2;
    scwin.fn_GetPar = fn_GetParIsur2;
    $c.lcd.fn_PopFindDigitalIsurAppl();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_ISUR_NM.setValue("");
    }
};
scwin.txb_ISU_CD_onblur = function() {
    if (txb_ISU_CD.getValue() == "") {
        txb_ISU_NM.setValue("");
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.img_1_onclick = async function() {
    scwin.fn_SetPar = fn_SetParIsu;
    scwin.fn_GetPar = fn_GetParIsu;
    await $c.frame.CreateDialogFrame("ULDSTF70017_3.gfm", "../digital/ULDSTF70017_3.gfm", "종목 선택", 10, 10, 430, 550 + 30, "window");
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
